-- New built-in programs (GRIZZ, 2026-10-11): 3-week Strength, Bodybuilding
-- and Weight loss blocks (4 days a week: Monday, Tuesday, Thursday, Friday,
-- 12 different sessions each, using 0065's weeks), plus 10 HIIT sessions.
-- Each comes with nutrition options. Written from current research
-- (volume and effort for muscle, heavy low-rep work for strength, resistance
-- training plus a moderate deficit and high protein for fat loss); the
-- notes are in the thread's programs-notes. Rep ranges let the app suggest
-- heavier weights from logged sets (src/lib/progression.ts).
--
-- Only inserted when a built-in program with the same name isn't there yet.

create or replace function pg_temp.add_program(p_name text, p_kind text, p_weeks int, p_description text, p_nutrition text, p_warm_up text, p_titles text[], p_rows jsonb)
returns void language plpgsql as $f$
declare
  prog uuid;
begin
  if exists (select 1 from public.programs where trainer_id is null and name = p_name) then
    return;
  end if;
  insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
  values (null, p_name, p_kind, 'gym', p_weeks, p_description, p_nutrition, p_warm_up, p_titles)
  returning id into prog;
  insert into public.program_exercises (program_id, week_number, day_number, sort_order, exercise_id, exercise_name, sets, reps, rest_seconds, kind)
  select prog, (r->>0)::smallint, (r->>1)::smallint, (r->>2)::smallint,
    case when r->>7 = 'exercise' then (select e.id from public.exercises e where e.name = r->>3 order by e.sort_order limit 1) end,
    r->>3, (r->>4)::smallint, r->>5, (r->>6)::smallint, r->>7
  from jsonb_array_elements(p_rows) r;
  if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.kind = 'exercise' and pe.exercise_id is null) then
    raise exception 'an exercise in % is not in the library', p_name;
  end if;
end $f$;

do $$
declare
  hiit_nutrition text := 'HIIT burns a lot in a short time, but your results still come down to what you eat. To lose fat, eat 15-25% below maintenance; to keep fit or build, eat at maintenance. Aim for 1.6-2.2 g of protein per kg a day. Have a small, easy-to-digest carb snack 60-90 minutes before, such as a banana, toast with honey or a rice cake with peanut butter. Afterwards, eat a meal with 25-40 g of protein and some carbs, such as chicken and rice, eggs on toast, or maas with fruit. Drink 500 ml of water in the 2 hours before and sip during the session. On hot days, add an electrolyte drink. Avoid a heavy meal in the 2 hours before, or the intervals will feel awful.';
  hiit_warm_up text := '5 minutes building from easy to moderate on the bike, rower or a light jog, then 1-2 rounds of 10 bodyweight squats, 10 walking lunges, 10 arm circles, 5 inchworms and 2 x 10-second build-up efforts at about 80% before the first hard interval.';
begin
  perform pg_temp.add_program('Strength 3-week block', 'weekly', 3, 'For lifters who want a bigger squat, bench, deadlift and row. You train upper and lower body twice a week with heavy main lifts first and long rests. Week 1 leaves 3 reps in the tank, week 2 adds a set and leaves 2, and week 3 is the heavy peak, leaving 1 rep in the tank. When you hit the top of the rep range on every set with clean form, add 2.5-5 kg next time. Sleep 7-9 hours, and after week 3 take an easy week (half the sets, lighter loads) or repeat the block heavier.',
    'Eat at maintenance or a small surplus of about 5-10% (roughly 150-300 kcal a day) so you have the fuel to lift heavy. Aim for 1.6-2.2 g of protein per kg of bodyweight a day, split over 3-5 meals. Keep carbs moderate to high (3-5 g/kg), especially in the meal 2-3 hours before training, with fats making up the rest (about 0.8-1 g/kg). Options: eggs, wholewheat toast and a banana for breakfast; chicken or lean beef mince with pap or rice and veg for lunch or dinner; maas or Greek yoghurt with fruit, or biltong and an apple, as snacks. Drink about 35 ml of water per kg a day, plus 500 ml per hour of training. Creatine monohydrate at 3-5 g a day is a safe, well-studied option for strength.', '5 minutes of easy bike or rower, then hip and thoracic mobility (leg swings, world''s greatest stretch, band pull-aparts). Before the first main lift, do ramp-up sets: empty bar x 10, then about 40%, 60%, 75% and 85% of your working weight for 5, 3, 2 and 1 reps.',
    array['Lower A – Squat','Upper A – Bench','Rest day','Lower B – Deadlift','Upper B – Row & Close-Grip','Rest day','Rest day','Lower A – Squat','Upper A – Bench','Rest day','Lower B – Deadlift','Upper B – Row & Close-Grip','Rest day','Rest day','Lower A – Squat','Upper A – Bench','Rest day','Lower B – Deadlift','Upper B – Row & Close-Grip','Rest day','Rest day'],
    '[[1, 1, 1, "Barbell Back Squat", 4, "5-6", 180, "exercise"], [1, 1, 2, "Romanian Deadlift", 3, "6-8", 150, "exercise"], [1, 1, 3, "Dumbbell Bulgarian Split Squat", 3, "8-10", 90, "exercise"], [1, 1, 4, "Lying Leg Curl", 3, "8-10", 90, "exercise"], [1, 1, 5, "Standing Calf Raise", 3, "8-12", 60, "exercise"], [1, 1, 6, "Kneeling Cable Crunch", 3, "10-12", 60, "exercise"], [1, 2, 1, "Bench Press", 4, "5-6", 180, "exercise"], [1, 2, 2, "Weighted Pull-Up", 4, "5-6", 180, "exercise"], [1, 2, 3, "Incline Dumbbell Press", 3, "6-8", 120, "exercise"], [1, 2, 4, "Chest-Supported Row", 3, "8-10", 90, "exercise"], [1, 2, 5, "Cable Seated Rope Face Pull", 3, "12-15", 60, "exercise"], [1, 2, 6, "EZ-Bar Curl", 3, "8-10", 60, "exercise"], [1, 4, 1, "Conventional Deadlift", 3, "4-6", 210, "exercise"], [1, 4, 2, "Front Squat", 3, "6-8", 150, "exercise"], [1, 4, 3, "Hip Thrust", 3, "6-8", 120, "exercise"], [1, 4, 4, "Leg Press", 3, "8-10", 90, "exercise"], [1, 4, 5, "Seated Leg Curl", 3, "8-10", 90, "exercise"], [1, 4, 6, "Seated Calf Raise", 3, "10-12", 60, "exercise"], [1, 4, 7, "Hanging Knee Raise", 3, "10-15", 60, "exercise"], [1, 5, 1, "Barbell Bent-Over Row", 4, "5-6", 180, "exercise"], [1, 5, 2, "Close-Grip Bench Press", 4, "5-6", 180, "exercise"], [1, 5, 3, "Neutral-Grip Lat Pulldown", 3, "8-10", 90, "exercise"], [1, 5, 4, "Dumbbell Lateral Raise", 3, "10-12", 60, "exercise"], [1, 5, 5, "Skull Crusher", 3, "8-10", 60, "exercise"], [1, 5, 6, "Hammer Curl", 3, "8-10", 60, "exercise"], [2, 1, 1, "Barbell Back Squat", 5, "4-6", 210, "exercise"], [2, 1, 2, "Romanian Deadlift", 3, "6-8", 150, "exercise"], [2, 1, 3, "Barbell Reverse Lunge", 3, "8-10", 90, "exercise"], [2, 1, 4, "Seated Leg Curl", 3, "8-10", 90, "exercise"], [2, 1, 5, "Seated Calf Raise", 3, "8-12", 60, "exercise"], [2, 1, 6, "Pallof Press", 3, "10-12", 60, "exercise"], [2, 2, 1, "Bench Press", 5, "4-6", 210, "exercise"], [2, 2, 2, "Weighted Pull-Up", 4, "4-6", 180, "exercise"], [2, 2, 3, "Incline Barbell Press", 3, "6-8", 120, "exercise"], [2, 2, 4, "Seated Cable Row", 3, "8-10", 90, "exercise"], [2, 2, 5, "Reverse Pec Deck", 3, "12-15", 60, "exercise"], [2, 2, 6, "Hammer Curl", 3, "8-10", 60, "exercise"], [2, 4, 1, "Conventional Deadlift", 4, "4-5", 240, "exercise"], [2, 4, 2, "Front Squat", 3, "5-7", 150, "exercise"], [2, 4, 3, "Hip Thrust", 3, "6-8", 120, "exercise"], [2, 4, 4, "Leg Press", 3, "8-10", 90, "exercise"], [2, 4, 5, "Lying Leg Curl", 3, "8-10", 90, "exercise"], [2, 4, 6, "Standing Calf Raise", 3, "10-12", 60, "exercise"], [2, 4, 7, "Captain''s Chair Knee Raise", 3, "10-15", 60, "exercise"], [2, 5, 1, "Barbell Bent-Over Row", 5, "4-6", 180, "exercise"], [2, 5, 2, "Close-Grip Bench Press", 4, "4-6", 180, "exercise"], [2, 5, 3, "Lat Pulldown", 3, "8-10", 90, "exercise"], [2, 5, 4, "Machine Lateral Raise", 3, "10-12", 60, "exercise"], [2, 5, 5, "V-Bar Cable Pushdown", 3, "8-10", 60, "exercise"], [2, 5, 6, "Incline Dumbbell Curl", 3, "8-10", 60, "exercise"], [3, 1, 1, "Barbell Back Squat", 4, "3-5", 240, "exercise"], [3, 1, 2, "Romanian Deadlift", 3, "5-7", 150, "exercise"], [3, 1, 3, "Dumbbell Bulgarian Split Squat", 3, "6-8", 90, "exercise"], [3, 1, 4, "Lying Leg Curl", 3, "8-10", 90, "exercise"], [3, 1, 5, "Standing Calf Raise", 3, "8-12", 60, "exercise"], [3, 1, 6, "Kneeling Cable Crunch", 3, "10-12", 60, "exercise"], [3, 2, 1, "Bench Press", 4, "3-5", 240, "exercise"], [3, 2, 2, "Weighted Pull-Up", 4, "3-5", 180, "exercise"], [3, 2, 3, "Incline Dumbbell Press", 3, "6-8", 120, "exercise"], [3, 2, 4, "Chest-Supported T-Bar Row", 3, "8-10", 90, "exercise"], [3, 2, 5, "Cable Bar Face Pull", 3, "12-15", 60, "exercise"], [3, 2, 6, "EZ-Bar Curl", 3, "8-10", 60, "exercise"], [3, 4, 1, "Conventional Deadlift", 4, "3-4", 240, "exercise"], [3, 4, 2, "Front Squat", 3, "4-6", 150, "exercise"], [3, 4, 3, "Hip Thrust", 3, "6-8", 120, "exercise"], [3, 4, 4, "Leg Press", 3, "8-10", 90, "exercise"], [3, 4, 5, "Seated Leg Curl", 3, "8-10", 90, "exercise"], [3, 4, 6, "Seated Calf Raise", 3, "10-12", 60, "exercise"], [3, 4, 7, "Hanging Knee Raise", 3, "10-15", 60, "exercise"], [3, 5, 1, "Barbell Bent-Over Row", 4, "4-6", 180, "exercise"], [3, 5, 2, "Close-Grip Bench Press", 4, "3-5", 180, "exercise"], [3, 5, 3, "Close-Grip Lat Pulldown", 3, "8-10", 90, "exercise"], [3, 5, 4, "Leaning Cable Lateral Raise", 3, "10-12", 60, "exercise"], [3, 5, 5, "Skull Crusher", 3, "8-10", 60, "exercise"], [3, 5, 6, "Hammer Curl", 3, "8-10", 60, "exercise"]]'::jsonb);
  perform pg_temp.add_program('Bodybuilding 3-week block', 'weekly', 3, 'For clients chasing muscle size. Each muscle is trained twice a week on an upper/lower split, building from about 12 hard sets per muscle in week 1 to about 15-18 in week 3. Week 1 leaves 2-3 reps in the tank, week 2 adds sets and leaves 1-2, and in week 3 take the last set of each exercise to 0-1 reps in reserve. When you hit the top of the rep range on every set, add weight next session; paired exercises with 0 rest are supersets. Sleep 7-9 hours, and after week 3 take a lighter week or repeat the block with heavier weights.',
    'For lean gains, eat about 5-10% above maintenance (around 200-350 kcal a day) and aim to gain 0.25-0.5% of bodyweight a week. Protein: 1.6-2.2 g per kg a day, with 25-40 g in each of 4 meals. Carbs fuel the volume, so aim for 4-6 g/kg, and keep fats around 0.8-1 g/kg. Meal ideas: scrambled eggs with wholewheat toast and avo; chicken thighs, rice and butternut; lean boerewors or mince with sweet potato and salad; tinned pilchards or tuna on toast; a pre-bed snack of maas, cottage cheese or Greek yoghurt. Drink 2.5-3.5 litres of water a day. Creatine monohydrate 3-5 g a day is worth taking.', '5 minutes of easy cardio, then 2 light sets of the first exercise of the day (about 50% and 75% of working weight for 8 and 4 reps). For later exercises, one lighter feeler set is enough if the target muscle is already warm.',
    array['Upper A – Chest & Back','Lower A – Quads','Rest day','Upper B – Back, Delts & Arms','Lower B – Hamstrings & Glutes','Rest day','Rest day','Upper A – Chest & Back','Lower A – Quads','Rest day','Upper B – Back, Delts & Arms','Lower B – Hamstrings & Glutes','Rest day','Rest day','Upper A – Chest & Back','Lower A – Quads','Rest day','Upper B – Back, Delts & Arms','Lower B – Hamstrings & Glutes','Rest day','Rest day'],
