  perform pg_temp.add_program('HIIT 1', 'quick', 1, '40/20 Bodyweight Burner. A no-equipment circuit for any space. Format: 40 sec on, 20 sec off, moving through the 5 exercises as a circuit; 4 rounds with 1 min rest between rounds (about 23 min). Work at an effort of 8/10 and keep the same quality of reps in round 4 as in round 1. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Jump Squat", 4, "40 sec", 20, "exercise"], [1, 1, 2, "Push-Up", 4, "40 sec", 20, "exercise"], [1, 1, 3, "Mountain Climber", 4, "40 sec", 20, "exercise"], [1, 1, 4, "Bodyweight Alternating Reverse Lunge", 4, "40 sec", 20, "exercise"], [1, 1, 5, "Burpee", 4, "40 sec", 60, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 2', 'quick', 1, 'Tabata Five. Five Tabata blocks, each 8 rounds of 20 sec all-out and 10 sec rest (4 min), with 1 min easy between blocks (about 24 min). This is genuinely maximal work, so if you can still talk in the last 10 seconds, push harder. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Assault bike", 1, "8 x 20 sec all-out / 10 sec easy", 60, "cardio"], [1, 1, 2, "Kettlebell Swing", 8, "20 sec", 10, "exercise"], [1, 1, 3, "Ski Erg", 1, "8 x 20 sec all-out / 10 sec easy", 60, "cardio"], [1, 1, 4, "Jump Squat", 8, "20 sec", 10, "exercise"], [1, 1, 5, "Mountain Climber", 8, "20 sec", 10, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 3', 'quick', 1, 'EMOM 24. Every minute on the minute for 24 minutes: start a new station at the top of each minute, do the reps, and rest for what is left of that minute. Rotate the 4 stations for 6 rounds. Pick a weight that leaves you 20-30 sec of rest each minute; if you get under 10 sec, go lighter. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Kettlebell Swing", 6, "12-15", 0, "exercise"], [1, 1, 2, "Burpee", 6, "8-10", 0, "exercise"], [1, 1, 3, "Goblet Squat", 6, "10-12", 0, "exercise"], [1, 1, 4, "Assault bike", 6, "30 sec hard each round", 0, "cardio"]]'::jsonb);
  perform pg_temp.add_program('HIIT 4', 'quick', 1, 'Treadmill Sprint Ladder. 10 rounds of 30 sec fast running and 90 sec walking (20 min), then a 4 min core finisher of 40 sec on, 20 sec off (about 26 min). Run the sprints at about 90% effort; set the speed so the last sprint is as fast as the first. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Treadmill", 1, "10 x 30 sec fast / 90 sec walk", 0, "cardio"], [1, 1, 2, "Dead Bug", 2, "40 sec", 20, "exercise"], [1, 1, 3, "Hand Plank", 2, "40 sec", 20, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 5', 'quick', 1, 'Ski Erg Pyramid + Dumbbell Circuit. Part 1: Ski Erg pyramid of 30, 60, 90, 60 and 30 sec hard, each followed by the same time easy (9 min). Part 2: 3 rounds of 30 sec on, 30 sec off through 4 exercises (12 min). With 1 min to switch, it takes about 22 min. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Ski Erg", 1, "30/60/90/60/30 sec hard, equal time easy", 0, "cardio"], [1, 1, 2, "Goblet Squat", 3, "30 sec", 30, "exercise"], [1, 1, 3, "Push-Up", 3, "30 sec", 30, "exercise"], [1, 1, 4, "Dumbbell Row", 3, "30 sec", 30, "exercise"], [1, 1, 5, "V-Up", 3, "30 sec", 30, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 6', 'quick', 1, 'Boxing Rounds. Six 2-minute rounds on the bag or pads with 1 min rest (18 min). In each rest minute, do 10 bodyweight squats. Finish with a 4-minute jump rope Tabata of 20 sec on, 10 sec off (about 23 min). Keep your hands up and punch from the hips. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Boxing", 1, "6 x 2 min rounds / 1 min rest", 60, "cardio"], [1, 1, 2, "Bodyweight Squat", 6, "10-12", 0, "exercise"], [1, 1, 3, "Jump Rope", 8, "20 sec", 10, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 7', 'quick', 1, 'Dumbbell 30/30 Circuit. A full-body circuit with one pair of dumbbells. Format: 30 sec on, 30 sec off through 5 exercises; 4 rounds with 1 min rest between rounds (about 23 min). Choose a weight you could lift for about 15 reps fresh, and go heavier once all 4 rounds feel controlled. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Goblet Squat", 4, "30 sec", 30, "exercise"], [1, 1, 2, "Dumbbell Row", 4, "30 sec", 30, "exercise"], [1, 1, 3, "Dumbbell Alternating Forward Lunge", 4, "30 sec", 30, "exercise"], [1, 1, 4, "Push-Up", 4, "30 sec", 30, "exercise"], [1, 1, 5, "Dumbbell Deadlift", 4, "30 sec", 60, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 8', 'quick', 1, 'Norwegian 4x4. 4 intervals of 4 min hard (about 85-95% of max heart rate, so you can only say a few words) with 3 min easy pedalling between them (25 min). This is a well-researched protocol for building aerobic fitness (VO2max). Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Cycle", 1, "4 x 4 min hard / 3 min easy", 0, "cardio"]]'::jsonb);
  perform pg_temp.add_program('HIIT 9', 'quick', 1, 'Sprint & Power. 8 sprints of 20 sec with about 100 sec walk-back recovery (16 min), then 4 rounds of 20 sec box jumps and 20 sec sled push, with 40 sec rest after each (about 8 min). Total about 25 min. Rest fully between sprints, because the goal is maximum speed, not exhaustion. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Sprint", 1, "8 x 20 sec sprint / 100 sec walk back", 0, "cardio"], [1, 1, 2, "Box Jump", 4, "20 sec", 40, "exercise"], [1, 1, 3, "Sled Push", 4, "20 sec", 40, "exercise"]]'::jsonb);
  perform pg_temp.add_program('HIIT 10', 'quick', 1, 'Engine Builder. Part 1: 40 sec on, 20 sec off through 5 stations; 4 rounds with 1 min rest between rounds (23 min). Part 2: an Assault bike Tabata of 8 x 20 sec all-out and 10 sec easy (4 min). Total about 28 min. Do 2-3 HIIT sessions a week, with 48 hours between them.',
    hiit_nutrition, hiit_warm_up,
    '{}'::text[],
    '[[1, 1, 1, "Battle Ropes", 4, "40 sec", 20, "exercise"], [1, 1, 2, "Kettlebell Swing", 4, "40 sec", 20, "exercise"], [1, 1, 3, "Rowing Sprint", 4, "40 sec", 20, "exercise"], [1, 1, 4, "Mountain Climber", 4, "40 sec", 20, "exercise"], [1, 1, 5, "Sled Push", 4, "40 sec", 60, "exercise"], [1, 1, 6, "Assault bike", 1, "8 x 20 sec all-out / 10 sec easy", 0, "cardio"]]'::jsonb);
